// Handle edge cases
if (points.size() <= 1) {
    return points;
}

// Find the point with the lowest y-coordinate (and leftmost if tie)
std::size_t pivot_index = 0;
for (std::size_t i = 1; i < points.size(); ++i) {
    if (points[i].y() < points[pivot_index].y() ||
        (points[i].y() == points[pivot_index].y() && points[i].x() < points[pivot_index].x())) {
        pivot_index = i;
    }
}

// Sort points by polar angle with pivot
std::vector<Point2d> sorted_points = points;
std::swap(sorted_points[0], sorted_points[pivot_index]);
std::sort(sorted_points.begin() + 1, sorted_points.end(),
    [&pivot = sorted_points[0]](const Point2d& a, const Point2d& b) {
        double cross = (a - pivot).cross(b - pivot);
        if (cross == 0) {
            return (a - pivot).squaredNorm() < (b - pivot).squaredNorm();
        }
        return cross > 0;
    });

// Remove collinear points
std::size_t m = 1;
for (std::size_t i = 1; i < sorted_points.size(); ++i) {
    while (i < sorted_points.size() - 1 &&
           (sorted_points[i] - sorted_points[0]).cross(sorted_points[i+1] - sorted_points[0]) == 0) {
        ++i;
    }
    sorted_points[m++] = sorted_points[i];
}
sorted_points.resize(m);

// Handle edge case where all points are collinear
if (sorted_points.size() <= 2) {
    return sorted_points;
}

// Build convex hull
std::vector<Point2d> hull;
hull.push_back(sorted_points[0]);
hull.push_back(sorted_points[1]);

for (std::size_t i = 2; i < sorted_points.size(); ++i) {
    while (hull.size() >= 2 &&
           (hull.back() - hull[hull.size()-2]).cross(sorted_points[i] - hull.back()) <= 0) {
        hull.pop_back();
    }
    hull.push_back(sorted_points[i]);
}

// Ensure the hull is closed (Graham-Andrew variant)
hull.push_back(sorted_points[0]);

// Remove duplicate point if any
if (hull.size() > 1 && hull.front() == hull.back()) {
    hull.pop_back();
}

return hull;

